import{_ as n,a0 as p,w as o,s as b,I as a,x as i,a1 as e,A as l,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何在 Ubuntu 上安装 GitLab | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上安装 GitLab | LCTT (202308) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上安装 GitLab | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上安装 GitLab | LCTT (202308) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04","title":"如何在 Ubuntu 上安装 GitLab","tag":"202308","desc":""},"relativePath":"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04.md","filePath":"[post].md"}'),h={name:"202308/20230727.1 ⭐️ How to Install GitLab on Ubuntu 22.04  20.04.md"};function g(r,t,u,c,k,f){const s=p("Link");return o(),b("div",null,[t[18]||(t[18]=a("h1",{id:"如何在-ubuntu-上安装-gitlab",tabindex:"-1"},[i("如何在 Ubuntu 上安装 GitLab "),a("a",{class:"header-anchor",href:"#如何在-ubuntu-上安装-gitlab","aria-label":"Permalink to “如何在 Ubuntu 上安装 GitLab”"},"​")],-1)),t[19]||(t[19]=a("p",null,[a("img",{src:"https://img.linux.net.cn/data/attachment/album/202308/08/113049el2dx242c4mwm40k.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=i("GitLab 是一个开源平台，提供了强大且功能丰富的解决方案，用于管理仓库、问题、CI/CD 管道等。如果你是 Ubuntu 22.04 或 20.04 用户，并且想要设置自己的 ",-1)),e(s,{href:"https://about.gitlab.com/"},{default:l(()=>[...t[0]||(t[0]=[i("GitLab",-1)])]),_:1}),t[2]||(t[2]=i(" 实例来简化你的 DevOps 工作流程，那么你来对地方了。",-1))]),t[20]||(t[20]=d(`<p>本分步指南将引导你完成 Ubuntu 22.04 或 20.04 上 GitLab 的安装过程。GItlab 提供企业版（Gitlab EE）和社区版（Gitlab CE）。在这篇文章中，我们将介绍社区版。</p><p>先决条件：</p><ul><li>运行 Ubuntu 22.04 或 20.04 且具有 SSH 访问权限的虚拟或专用服务器。</li><li>静态主机名（<code>gitlab.linuxtechi.net</code>）</li><li>具有管理员权限的 Sudo 用户</li><li>2GB 内存或更多</li><li>2 个或更多 vCPU</li><li>互联网连接</li></ul><h3 id="_1、更新系统包" tabindex="-1">1、更新系统包 <a class="header-anchor" href="#_1、更新系统包" aria-label="Permalink to “1、更新系统包”">​</a></h3><p>让我们首先更新软件包列表并将任何现有软件包升级到最新版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt upgrade -y</span></span></code></pre></div><p>应用更新后重新启动系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="_2、安装依赖项" tabindex="-1">2、安装依赖项 <a class="header-anchor" href="#_2、安装依赖项" aria-label="Permalink to “2、安装依赖项”">​</a></h3><p>GitLab 需要一些依赖项才能正常运行。使用以下命令安装它们：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install -y curl openssh-server ca-certificates postfix</span></span></code></pre></div><p>在 postfix 安装过程中，会出现一个配置窗口。选择 “Internet Site”并输入服务器的主机名作为邮件服务器名称。这将允许 GitLab 发送电子邮件通知。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Choose-Internet-Site-Postfix-Gitlab-Installation-Ubuntu.png" alt=""></p><p>选择 “Internet Site”，然后选择 “OK”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/System-Hostname-Postfix-Gitlab-Ubuntu.png" alt=""></p><p>检查系统的主机名并选择 “OK”。</p><h3 id="_3、添加-gitlab-apt-存储库" tabindex="-1">3、添加 GitLab Apt 存储库 <a class="header-anchor" href="#_3、添加-gitlab-apt-存储库" aria-label="Permalink to “3、添加 GitLab Apt 存储库”">​</a></h3><p>现在，我们将添加 GitLab 仓库，运行以下 <code>curl</code> 命令。它将自动检测你的 Ubuntu 版本并相应地设置仓库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ curl -sS https://packages.gitlab.com/install/repositories/gitlab/gitlab-ce/script.deb.sh | sudo bash</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Add-GitLAb-CE-Apt-Repository-Ubuntu.png" alt=""></p><h3 id="_4、安装-gitlab" tabindex="-1">4、安装 Gitlab <a class="header-anchor" href="#_4、安装-gitlab" aria-label="Permalink to “4、安装 Gitlab”">​</a></h3><p>运行以下命令在你的 ubuntu 系统上自动安装和配置 gitlab-ce，将服务器的主机名替换为你的设置，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo EXTERNAL_URL=&quot;http://gitlab.linuxtechi.net&quot; apt install gitlab-ce</span></span></code></pre></div><p>上述命令成功执行后，我们将得到如下输出。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Apt-Install-Gitlab-ce-Ubuntu.png" alt=""></p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-Successful-Installlation-Message-Ubuntu.png" alt=""></p><p>上面的输出确认 GitLab 已成功安装。gitlab web 界面的用户名是 root，密码存储在 <code>/etc/gitlab/initial_root_password</code>。</p><p>注意：如果你的 ubuntu 系统上启用了操作系统防火墙，那请允许 80 和 443 端口。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ufw allow http</span></span>
<span class="line"><span>$ sudo ufw allow https</span></span></code></pre></div><h3 id="_5、访问-gitlab-web-界面" tabindex="-1">5、访问 GitLab Web 界面 <a class="header-anchor" href="#_5、访问-gitlab-web-界面" aria-label="Permalink to “5、访问 GitLab Web 界面”">​</a></h3><p>安装并配置 GitLab 后，打开 Web 浏览器并输入服务器的 IP 地址或主机名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>http://&lt;Server-IP-Address-or-Hostname&gt;</span></span></code></pre></div><ul><li>用户名：<code>root</code></li><li>密码：从 <code>/etc/gitlab/initial_root_password</code> 获取密码</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/GitLab-Login-Page-Post-Installation-Ubuntu.png" alt=""></p><p>点击“<ruby>登录<rt>Sign in</rt></ruby>”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/GitLab-Web-Interface-Ubuntu.png" alt=""></p><p>很好，上面确认我们已经成功登录 Gitlab Web 界面。</p><p>目前我们的 GitLab 服务器运行在 http（80）协议上，如果你想为你的 GitLab 启用 https，请参考以下步骤。</p><h3 id="_6、为-gitlab-web-界面设置-https" tabindex="-1">6、为 GitLab Web 界面设置 HTTPS <a class="header-anchor" href="#_6、为-gitlab-web-界面设置-https" aria-label="Permalink to “6、为 GitLab Web 界面设置 HTTPS”">​</a></h3><p>为提高安全性，可使用自签名证书或 Let&#39;s Encrypt 为 GitLab 实例配置 HTTPS。Let&#39;s Encrypt 只适用于互联网上有 A 记录的公有域。但在本例中，我们使用的是私有域，因此将使用自签名证书来确保 GitLab 的安全。</p><p>现在，让我们创建以下文件夹并使用 <code>openssl</code> 命令生成自签名证书：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkdir -p /etc/gitlab/ssl</span></span>
<span class="line"><span>$ sudo chmod 755 /etc/gitlab/ssl</span></span></code></pre></div><p>使用以下 <code>openssl</code> 命令生成私钥：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl genrsa -des3 -out /etc/gitlab/ssl/gitlab.linuxtechi.net.key 2048</span></span></code></pre></div><p>输入密码并记住它。</p><p>使用以下命令创建 CSR：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl req -new -key /etc/gitlab/ssl/gitlab.linuxtechi.net.key -out /etc/gitlab/ssl/gitlab.linuxtechi.net.csr</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Generate-CSR-Self-Sign-Cert-Gitlab.png" alt=""></p><p>从密钥中删除密码串，依次执行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo cp -v /etc/gitlab/ssl/gitlab.linuxtechi.net.{key,original}</span></span>
<span class="line"><span>$ sudo openssl rsa -in /etc/gitlab/ssl/gitlab.linuxtechi.net.original -out /etc/gitlab/ssl/gitlab.linuxtechi.net.key</span></span>
<span class="line"><span>$ sudo rm -v /etc/gitlab/ssl/gitlab.linuxtechi.net.original</span></span></code></pre></div><p>创建证书文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo openssl x509 -req -days 1460 -in /etc/gitlab/ssl/gitlab.linuxtechi.net.csr -signkey /etc/gitlab/ssl/gitlab.linuxtechi.net.key -out /etc/gitlab/ssl/gitlab.linuxtechi.net.crt</span></span></code></pre></div><p>使用下面的 <code>rm</code> 命令删除 CSR 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo rm -v /etc/gitlab/ssl/gitlab.linuxtechi.net.csr</span></span></code></pre></div><p>设置密钥和证书文件的权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo chmod 600 /etc/gitlab/ssl/gitlab.linuxtechi.net.key</span></span>
<span class="line"><span>$ sudo chmod 600 /etc/gitlab/ssl/gitlab.linuxtechi.net.crt</span></span></code></pre></div><p>Gitlab 服务器的所有重要配置均由文件 <code>/etc/gitlab/gitlab.rb</code> 控制，因此编辑此文件，搜索 <code>external_url</code> 并添加 <code>https://gitlab.linuxtechi.net</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo vi /etc/gitlab/gitlab.rb</span></span>
<span class="line"><span>----------------------------------------------------------</span></span>
<span class="line"><span>external_url &#39;https://gitlab.linuxtechi.net&#39;</span></span>
<span class="line"><span>----------------------------------------------------------</span></span></code></pre></div><p>保存并退出文件，使用下面的命令重新配置 gitlab，以便其 Web 界面可以使用 HTTPS。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo gitlab-ctl reconfigure</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-reconfigured-Ubuntu.png" alt=""></p><p>成功执行上述命令后，你的 GitLab 界面应该可以通过 HTTPS 协议访问，在我的例子中，URL 为：<code>https://gitlab.linuxtechi.net/</code></p><p>当你第一次访问它时，它会说你的连接不安全，点击“接受风险并继续”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/06/Gitlab-Web-Interface-over-Https-Ubuntu.png" alt=""></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>恭喜！ 你已在 Ubuntu 22.04 或 20.04 系统上成功安装 GitLab。随着 GitLab 的启动和运行，你现在可以创建仓库，与你的团队协作，并通过 GitLab 令人印象深刻的功能增强你的开发工作流程。享受无缝版本控制、持续集成等，一切尽在你的掌控之中！</p><p><em>（题图：MJ/c6a3e27e-fe58-4184-b133-9e9c67224316）</em></p><hr>`,68)),a("p",null,[t[4]||(t[4]=i("via: ",-1)),e(s,{href:"https://www.linuxtechi.com/how-to-install-gitlab-on-ubuntu/"},{default:l(()=>[...t[3]||(t[3]=[i("https://www.linuxtechi.com/how-to-install-gitlab-on-ubuntu/",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=i("作者：",-1)),e(s,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:l(()=>[...t[5]||(t[5]=[i("Pradeep Kumar",-1)])]),_:1}),t[10]||(t[10]=i(" 选题：",-1)),e(s,{href:"https://github.com/lkxed/"},{default:l(()=>[...t[6]||(t[6]=[i("lkxed",-1)])]),_:1}),t[11]||(t[11]=i(" 译者：",-1)),e(s,{href:"https://github.com/geekpi"},{default:l(()=>[...t[7]||(t[7]=[i("geekpi",-1)])]),_:1}),t[12]||(t[12]=i(" 校对：",-1)),e(s,{href:"https://github.com/wxy"},{default:l(()=>[...t[8]||(t[8]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=i("本文由 ",-1)),e(s,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[13]||(t[13]=[i("LCTT",-1)])]),_:1}),t[16]||(t[16]=i(" 原创编译，",-1)),e(s,{href:"https://linux.cn/"},{default:l(()=>[...t[14]||(t[14]=[i("Linux中国",-1)])]),_:1}),t[17]||(t[17]=i(" 荣誉推出",-1))])])}const y=n(h,[["render",g]]);export{w as __pageData,y as default};
